<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

function kimpu_register_dark_mode_controls( $customizer ) {
	$section = 'kimpu_design_dark_mode'; $customizer->add_section( $section, array( 'title' => __( 'Light / Dark Mode', 'kimpu-multipurpose' ), 'panel' => 'kimpu_global_design', 'priority' => 70 ) );
	$customizer->add_setting( 'kimpu_theme_mode', array( 'default' => 'system', 'sanitize_callback' => function( $v ) { return kimpu_sanitize_design_choice( $v, array( 'light', 'dark', 'system' ), 'system' ); }, 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_theme_mode', array( 'label' => __( 'Global Theme Mode', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'select', 'choices' => array( 'light' => __( 'Light', 'kimpu-multipurpose' ), 'dark' => __( 'Dark', 'kimpu-multipurpose' ), 'system' => __( 'System Preference', 'kimpu-multipurpose' ) ) ) );
	$customizer->add_setting( 'kimpu_theme_toggle_enabled', array( 'default' => true, 'sanitize_callback' => 'rest_sanitize_boolean', 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_theme_toggle_enabled', array( 'label' => __( 'Show Frontend Mode Switcher', 'kimpu-multipurpose' ), 'description' => __( 'The switcher appears in the header and mobile navigation.', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'checkbox' ) );
	$colors = array( 'dark_background' => array( '#0f1720', __( 'Dark Body Background', 'kimpu-multipurpose' ) ), 'dark_surface' => array( '#17232d', __( 'Dark Surface', 'kimpu-multipurpose' ) ), 'dark_card' => array( '#1e2d38', __( 'Dark Card', 'kimpu-multipurpose' ) ), 'dark_heading' => array( '#f8fafc', __( 'Dark Heading Text', 'kimpu-multipurpose' ) ), 'dark_text' => array( '#d7e1e8', __( 'Dark Body Text', 'kimpu-multipurpose' ) ), 'dark_muted' => array( '#9fb0bd', __( 'Dark Muted Text', 'kimpu-multipurpose' ) ), 'dark_border' => array( '#334552', __( 'Dark Border', 'kimpu-multipurpose' ) ) ); foreach ( $colors as $key => $data ) { kimpu_add_design_color( $customizer, 'kimpu_design_' . $key, $data[0], $data[1], $section ); }
}
